// Canvas adapter for the original Arknights Spine 3.5 enemy files.
// Reads region attachments, weighted meshes, bone timelines, IK and draw order.
// No game executable or external runtime is loaded.
const EnemyAssets={soldier:null,shield:null,ready:false,error:''};
function assetImage(src){return new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=()=>reject(new Error('Asset unavailable: '+src));image.src=src})}
function atlasRegions(text){const blocks=text.trim().split(/\r?\n/),regions={};let current;for(let i=1;i<blocks.length;i++){const s=blocks[i];if(!s.trim())continue;if(!/^\s/.test(s)&&!s.includes(':')){current={};regions[s.trim()]=current}else if(current){const [k,...v]=s.trim().split(':');current[k]=v.join(':').trim()}}return regions}
const rad=Math.PI/180;
function matMultiply(a,b){return [a[0]*b[0]+a[2]*b[1],a[1]*b[0]+a[3]*b[1],a[0]*b[2]+a[2]*b[3],a[1]*b[2]+a[3]*b[3],a[0]*b[4]+a[2]*b[5]+a[4],a[1]*b[4]+a[3]*b[5]+a[5]]}
function point(m,x,y){return [m[0]*x+m[2]*y+m[4],m[1]*x+m[3]*y+m[5]]}
function sampleFrame(frames,t,defaults){if(!frames?.length)return defaults;let a=frames[0];if(t<(a.time||0))return defaults;let b;for(let i=1;i<frames.length;i++){if((frames[i].time||0)>t){b=frames[i];break}a=frames[i]}if(!b||a.curve==='stepped')return {...defaults,...a};let f=(t-(a.time||0))/((b.time||0)-(a.time||0));if(Array.isArray(a.curve)){const [x1,y1,x2,y2]=a.curve;let lo=0,hi=1;for(let j=0;j<8;j++){let q=(lo+hi)/2,x=3*(1-q)*(1-q)*q*x1+3*(1-q)*q*q*x2+q*q*q;if(x<f)lo=q;else hi=q}let q=(lo+hi)/2;f=3*(1-q)*(1-q)*q*y1+3*(1-q)*q*q*y2+q*q*q}const out={...defaults};for(const k of Object.keys(defaults)){if(typeof defaults[k]==='string'){out[k]=a[k]||defaults[k];continue}let v=a[k]??defaults[k],delta=(b[k]??defaults[k])-v;if(k==='angle')delta=((delta+180)%360+360)%360-180;out[k]=v+delta*f}return out}
function animationDuration(a){let max=0;function visit(o){if(!o||typeof o!=='object')return;if(typeof o.time==='number')max=Math.max(max,o.time);for(const v of Object.values(o))visit(v)}visit(a);return Math.max(max,.1)}
class EnemySkeleton{
 constructor(data,atlas,image){this.data=data;this.image=image;this.regions=atlasRegions(atlas);this.boneIndex=Object.fromEntries(data.bones.map((b,i)=>[b.name,i]));this.durations=Object.fromEntries(Object.entries(data.animations).map(([name,a])=>[name,animationDuration(a)]));this.skin=data.skins.default;this.regionImages={};this.frames={};this.buildRegions();this.bounds=this.findBounds()}
 buildRegions(){for(const [name,r] of Object.entries(this.regions)){const [x,y]=r.xy.split(',').map(Number),[w,h]=r.size.split(',').map(Number),[ow,oh]=(r.orig||r.size).split(',').map(Number),[ox,oy]=(r.offset||'0,0').split(',').map(Number);const c=document.createElement('canvas');c.width=ow;c.height=oh;const g=c.getContext('2d');if(r.rotate==='true'){g.save();g.translate(ox,oh-oy);g.rotate(-Math.PI/2);g.drawImage(this.image,x,y,h,w,0,0,h,w);g.restore()}else g.drawImage(this.image,x,y,w,h,ox,oh-oy-h,w,h);this.regionImages[name]=c}}
 pose(name,t){const anim=this.data.animations[name]||this.data.animations.Idle||{},seconds=t%(this.durations[name]||1),locals=this.data.bones.map(b=>{const timeline=anim.bones?.[b.name],tr=sampleFrame(timeline?.translate,seconds,{x:0,y:0}),ro=sampleFrame(timeline?.rotate,seconds,{angle:0}),sc=sampleFrame(timeline?.scale,seconds,{x:1,y:1});return {x:(b.x||0)+tr.x,y:(b.y||0)+tr.y,rotation:(b.rotation||0)+ro.angle,sx:(b.scaleX??1)*sc.x,sy:(b.scaleY??1)*sc.y}});const world=[];const update=()=>{for(let i=0;i<locals.length;i++){const l=locals[i],a=l.rotation*rad,local=[Math.cos(a)*l.sx,Math.sin(a)*l.sx,-Math.sin(a)*l.sy,Math.cos(a)*l.sy,l.x,l.y],parent=this.data.bones[i].parent;world[i]=parent?matMultiply(world[this.boneIndex[parent]],local):local}};update();
 // Solve constraints in original evaluation order, then rebuild descendant transforms.
 for(const ik of [...(this.data.ik||[])].sort((a,b)=>a.order-b.order)){const target=world[this.boneIndex[ik.target]];if(!target)continue;const mix=sampleFrame(anim.ik?.[ik.name],seconds,{mix:ik.mix??1}).mix,indices=ik.bones.map(n=>this.boneIndex[n]);if(indices.length===1){const i=indices[0],b=world[i],angle=Math.atan2(target[5]-b[5],target[4]-b[4])/rad-Math.atan2(b[1],b[0])/rad;locals[i].rotation+=(((angle+180)%360+360)%360-180)*mix;update()}else if(indices.length===2){const [pi,ci]=indices,pa=world[pi],ch=world[ci],a=Math.hypot(ch[4]-pa[4],ch[5]-pa[5]),len=(this.data.bones[ci].length||1)*Math.hypot(ch[0],ch[1]),dx=target[4]-pa[4],dy=target[5]-pa[5],dist=Math.hypot(dx,dy),bend=ik.bendPositive===false?-1:1;if(a>.01&&len>.01){const elbow=Math.acos(Math.max(-1,Math.min(1,(dist*dist-a*a-len*len)/(2*a*len))))*bend,angle=Math.atan2(dy,dx)-Math.atan2(len*Math.sin(elbow),a+len*Math.cos(elbow)),current=Math.atan2(ch[5]-pa[5],ch[4]-pa[4]);locals[pi].rotation+=((angle-current)/rad)*mix;update();const childAngle=Math.atan2(world[ci][1],world[ci][0]),parentAngle=Math.atan2(world[pi][1],world[pi][0]);let delta=(parentAngle+elbow-childAngle)/rad;locals[ci].rotation+=(((delta+180)%360+360)%360-180)*mix;update()}}}
 const slots=this.data.slots.map(s=>{let attach=s.attachment;for(const f of anim.slots?.[s.name]?.attachment||[])if((f.time||0)<=seconds)attach=f.name;const color=sampleFrame(anim.slots?.[s.name]?.color,seconds,{color:s.color||'ffffffff'}).color;return {slot:s,attachment:attach,color}});let order=slots;const drawFrame=(anim.drawOrder||anim.draworder||[]).filter(f=>(f.time||0)<=seconds).at(-1);if(drawFrame?.offsets){order=slots.slice();const unchanged=[],moved=new Set();for(const o of drawFrame.offsets){let i=slots.findIndex(s=>s.slot.name===o.slot);if(i<0)continue;order[i+o.offset]=slots[i];moved.add(i)}for(let i=0;i<slots.length;i++)if(!moved.has(i))unchanged.push(slots[i]);const explicit=new Set(drawFrame.offsets.map(o=>slots.findIndex(s=>s.slot.name===o.slot)+o.offset));for(let i=0;i<order.length;i++)if(!explicit.has(i))order[i]=unchanged.shift()}
 return {world,slots:order}}
 vertices(a,world,slot){if(a.type!=='mesh'){const b=world[this.boneIndex[slot.bone]],ang=(a.rotation||0)*rad,local=[Math.cos(ang)*(a.scaleX??1),Math.sin(ang)*(a.scaleX??1),-Math.sin(ang)*(a.scaleY??1),Math.cos(ang)*(a.scaleY??1),a.x||0,a.y||0],m=matMultiply(b,local),w=a.width/2,h=a.height/2;return [[-w,-h],[-w,h],[w,h],[w,-h]].map(v=>point(m,...v))}const out=[],v=a.vertices;if(v.length===a.uvs.length){const b=world[this.boneIndex[slot.bone]];for(let i=0;i<v.length;i+=2)out.push(point(b,v[i],v[i+1]));return out}let cursor=0;while(cursor<v.length){const count=v[cursor++];let x=0,y=0;for(let i=0;i<count;i++){const b=world[v[cursor++]],p=point(b,v[cursor++],v[cursor++]),weight=v[cursor++];x+=p[0]*weight;y+=p[1]*weight}out.push([x,y])}return out}
 findBounds(){const pose=this.pose('Idle',0),points=[];for(const s of pose.slots){const a=this.skin[s.slot.name]?.[s.attachment];if(a)points.push(...this.vertices(a,pose.world,s.slot))}return {minX:Math.min(...points.map(v=>v[0])),maxX:Math.max(...points.map(v=>v[0])),minY:Math.min(...points.map(v=>v[1])),maxY:Math.max(...points.map(v=>v[1]))}}
 renderFrame(name,t){const key=name+':'+Math.floor((t%(this.durations[name]||1))*24);if(this.frames[key])return this.frames[key];const c=document.createElement('canvas');c.width=320;c.height=400;const g=c.getContext('2d'),pose=this.pose(name,t),b=this.bounds,scale=330/(b.maxY-b.minY);g.translate(160,370);g.scale(scale,-scale);g.translate(-(b.minX+b.maxX)/2,-b.minY);for(const s of pose.slots){const a=this.skin[s.slot.name]?.[s.attachment],img=a&&this.regionImages[a.path||a.name||s.attachment];if(!a||!img)continue;const v=this.vertices(a,pose.world,s.slot);g.save();const color=s.color||'ffffffff';g.globalAlpha=parseInt(color.slice(6,8)||'ff',16)/255;if(a.type==='mesh'){for(let j=0;j<a.triangles.length;j+=3){const ids=a.triangles.slice(j,j+3),src=ids.map(i=>[a.uvs[i*2]*img.width,a.uvs[i*2+1]*img.height]),dst=ids.map(i=>v[i]);drawTextureTriangle(g,img,src,dst)}}else{const x=v[1],y=v[2],z=v[0];g.transform((y[0]-x[0])/img.width,(y[1]-x[1])/img.width,(z[0]-x[0])/img.height,(z[1]-x[1])/img.height,x[0],x[1]);g.drawImage(img,0,0)}g.restore()}if(Object.keys(this.frames).length>130)this.frames={};this.frames[key]=c;return c}
}
function drawTextureTriangle(c,image,s,d){const [s0,s1,s2]=s,[d0,d1,d2]=d,det=(s1[0]-s0[0])*(s2[1]-s0[1])-(s2[0]-s0[0])*(s1[1]-s0[1]);if(Math.abs(det)<.001)return;const a=((d1[0]-d0[0])*(s2[1]-s0[1])-(d2[0]-d0[0])*(s1[1]-s0[1]))/det,b=((d1[1]-d0[1])*(s2[1]-s0[1])-(d2[1]-d0[1])*(s1[1]-s0[1]))/det,cc=((s1[0]-s0[0])*(d2[0]-d0[0])-(s2[0]-s0[0])*(d1[0]-d0[0]))/det,dd=((s1[0]-s0[0])*(d2[1]-d0[1])-(s2[0]-s0[0])*(d1[1]-d0[1]))/det;c.save();c.beginPath();c.moveTo(...d0);c.lineTo(...d1);c.lineTo(...d2);c.closePath();c.clip();c.transform(a,b,cc,dd,d0[0]-a*s0[0]-cc*s0[1],d0[1]-b*s0[0]-dd*s0[1]);c.drawImage(image,0,0);c.restore()}
async function loadEnemyAssets(){try{await Promise.all(['soldier','shield'].map(async name=>{const [json,atlas,img]=await Promise.all([fetch('assets/'+name+'.json').then(r=>{if(!r.ok)throw new Error(name);return r.json()}),fetch('assets/'+name+'.atlas').then(r=>r.text()),assetImage('assets/'+name+'-atlas.png')]);EnemyAssets[name]=new EnemySkeleton(json,atlas,img)}));EnemyAssets.ready=true;if(typeof refreshAssetStatus==='function')refreshAssetStatus()}catch(e){EnemyAssets.error=e.message;if(typeof refreshAssetStatus==='function')refreshAssetStatus();console.error('Enemy asset loading failed',e)}}
if(typeof Image!=='undefined')loadEnemyAssets();
